local GardenTrowelMaker = {}
local PRODUCTS = {
    iron_trowel = { name = "Železna vrtna lopatka", ironCost = 2, woodCost = 1, leatherCost = 1, time = 4, cost = 115, prestige = 2, happiness = 1, description = "Železna vrtna lopatka za sajenje." },
    bronze_trowel = { name = "Bronasta vrtna lopatka", bronzeCost = 2, ironCost = 1, woodCost = 1, leatherCost = 1, time = 6, cost = 290, prestige = 4, happiness = 2, description = "Bronasta vrtna lopatka za trdo zemljo." },
    silver_trowel = { name = "Srebrna vrtna lopatka", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 10, cost = 730, prestige = 8, happiness = 3, description = "Srebrna vrtna lopatka za plemiške vrtove." },
    gilded_trowel = { name = "Pozlačena vrtna lopatka", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 14, cost = 1620, prestige = 16, happiness = 4, description = "Pozlačena vrtna lopatka za dvorne vrtove." },
    jewel_set_trowel = { name = "Draguljasta vrtna lopatka", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 18, cost = 3550, prestige = 31, happiness = 6, description = "Draguljasta vrtna lopatka za kraljeve vrtove." },
    royal_sovereign_trowel = { name = "Kraljevski suverena vrtna lopatka", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 25, cost = 7900, prestige = 62, happiness = 12, description = "Suverena vrtna lopatka z biseri za krono." },
}
local BUILDINGS = {
    trowel_workshop = { name = "Lopatkarska delavnica", cost = { gold = 280, wood = 165, stone = 120, iron = 5 }, upkeep = 5, qualityBonus = 5 },
    trowel_house = { name = "Lopatkarska hiša", cost = { gold = 1050, wood = 335, stone = 245, silver = 6, iron = 6 }, upkeep = 22, qualityBonus = 18 },
    master_trowel_atelier = { name = "Mojstrski lopatkarski atelje", cost = { gold = 2800, wood = 395, stone = 490, silver = 30, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    sovereign_trowel_palace = { name = "Suverena lopatkarska palača", cost = { gold = 12000, wood = 605, stone = 800, gold = 78, jewel = 17 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
GardenTrowelMaker.ironStock = 12; GardenTrowelMaker.bronzeStock = 10; GardenTrowelMaker.woodStock = 14; GardenTrowelMaker.leatherStock = 10; GardenTrowelMaker.silverStock = 8; GardenTrowelMaker.goldStock = 6; GardenTrowelMaker.jewelStock = 4; GardenTrowelMaker.pearlStock = 4
GardenTrowelMaker.productStock = {}; GardenTrowelMaker.buildings = {}; GardenTrowelMaker.maker = nil; GardenTrowelMaker.activeMaking = {}; GardenTrowelMaker.totalProducts = 0; GardenTrowelMaker.dayTimer = 0
function GardenTrowelMaker.init() GardenTrowelMaker.ironStock=12; GardenTrowelMaker.bronzeStock=10; GardenTrowelMaker.woodStock=14; GardenTrowelMaker.leatherStock=10; GardenTrowelMaker.silverStock=8; GardenTrowelMaker.goldStock=6; GardenTrowelMaker.jewelStock=4; GardenTrowelMaker.pearlStock=4; GardenTrowelMaker.productStock={}; GardenTrowelMaker.buildings={}; GardenTrowelMaker.maker=nil; GardenTrowelMaker.activeMaking={}; GardenTrowelMaker.totalProducts=0; GardenTrowelMaker.dayTimer=0; print("[GardenTrowelMaker] Royal Garden Trowel Maker System initialized (6 products, 4 buildings)") end
function GardenTrowelMaker.hireMaker(n,s) s=s or math.random(55,90); local c=565+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenTrowelMaker.maker={name=n or ("Lopatkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lopatkar najet: %s (spretnost: %d)",GardenTrowelMaker.maker.name,s),"success") end; return true end
function GardenTrowelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenTrowelMaker.build(id) local ok,e=GardenTrowelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenTrowelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenTrowelMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenTrowelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenTrowelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenTrowelMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenTrowelMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenTrowelMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenTrowelMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenTrowelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenTrowelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenTrowelMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenTrowelMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenTrowelMaker.buildings==0 then return false,"Potrebna lopatkarska delavnica" end; if not GardenTrowelMaker.maker then return false,"Potreben lopatkar" end; return true end
function GardenTrowelMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenTrowelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenTrowelMaker.ironStock=GardenTrowelMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenTrowelMaker.bronzeStock=GardenTrowelMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenTrowelMaker.woodStock=GardenTrowelMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenTrowelMaker.leatherStock=GardenTrowelMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenTrowelMaker.silverStock=GardenTrowelMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenTrowelMaker.goldStock=GardenTrowelMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenTrowelMaker.jewelStock=GardenTrowelMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenTrowelMaker.pearlStock=GardenTrowelMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenTrowelMaker.maker then t=math.max(1,t-math.floor(GardenTrowelMaker.maker.skill/13)) end; table.insert(GardenTrowelMaker.activeMaking,{id="trowel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenTrowelMaker.completeMaking(m) local q=1.0+(GardenTrowelMaker.getQualityBonus()/100); if GardenTrowelMaker.maker then q=q+(GardenTrowelMaker.maker.skill/140) end; q=math.min(2.5,q); GardenTrowelMaker.productStock[m.productType]=(GardenTrowelMaker.productStock[m.productType] or 0)+m.quantity; GardenTrowelMaker.totalProducts=GardenTrowelMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenTrowelMaker.maker then GardenTrowelMaker.maker.itemsMade=GardenTrowelMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenTrowelMaker.maker.skill=math.min(100,GardenTrowelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lopatka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"trowel.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenTrowelMaker.update(dt) if not _G.state then return end; GardenTrowelMaker.dayTimer=GardenTrowelMaker.dayTimer+dt; if GardenTrowelMaker.dayTimer>=30 then GardenTrowelMaker.dayTimer=0; for i=#GardenTrowelMaker.activeMaking,1,-1 do local m=GardenTrowelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenTrowelMaker.completeMaking(m); table.remove(GardenTrowelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenTrowelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenTrowelMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenTrowelMaker.getStats() return {ironStock=GardenTrowelMaker.ironStock,bronzeStock=GardenTrowelMaker.bronzeStock,woodStock=GardenTrowelMaker.woodStock,leatherStock=GardenTrowelMaker.leatherStock,silverStock=GardenTrowelMaker.silverStock,goldStock=GardenTrowelMaker.goldStock,jewelStock=GardenTrowelMaker.jewelStock,pearlStock=GardenTrowelMaker.pearlStock,productStock=GardenTrowelMaker.productStock,numBuildings=#GardenTrowelMaker.buildings,hasMaker=GardenTrowelMaker.maker~=nil,makerName=GardenTrowelMaker.maker and GardenTrowelMaker.maker.name or "—",makerSkill=GardenTrowelMaker.maker and GardenTrowelMaker.maker.skill or 0,activeMaking=#GardenTrowelMaker.activeMaking,totalProducts=GardenTrowelMaker.totalProducts} end
return GardenTrowelMaker
